import React, { Component } from 'react';
import Infographics from './Infographics';
import Crypto from './Crypto';
import Newsflash from './Newsflash';
import Bitcoingraph from './Bitcoingraph';
import Highlightsy from './Highlightsy';
import Orders from './Orders';
import Activeorders from './Activeorders';
import Orderstable from './Orderstable';
import Scatterchart from './Scatterchart';
import Marketpos from './Marketpos';
import {Services} from "../../../Services";
import RecentPayments from "./RecentPayments";
class Content extends Component {
  constructor(props) {
    super();
    this.state = {
      stats: {}, data: [], labels: []
    }
    this.services = new Services(this);
    // this.funcs = new Funcs
  }

  componentDidMount() {
    let _this = this;
    this.services.getData("dashboard").then(res=>{
      _this.setState({stats: res.data.dashboard})
      let labels = [];
      let data = []
      let items = res.data.orderGrap;
      for (let i=0; i<items.length; i++){
        var obj = items[i];
        labels.push(obj.orderDate);
        data.push(obj.frequency);
      }
      _this.setState({labels:labels, data:data})
      // console.log(res.data)
    }).catch(err=>{
      console.warn(err)
    })
  }

  render() {
        return (
            <div className="ms-content-wrapper">
                <div className="row">
                    <Newsflash/>
                    <Infographics stats={this.state.stats}/>
                    <Bitcoingraph data={this.state.data} labels={this.state.labels}/>
                    <Activeorders/>
                  <RecentPayments/>
                  <Orderstable/>
                </div>
            </div>
        );
    }
}

export default Content;
