import React, { Component } from 'react';
import Slider from 'react-slick';

const news = [
    {
        title: 'Taam Petroleum is now registered and approved to operate in 6 African countries starting November 2022. '
    },
    {
        title: ' Invite your family and friends to use Taam Products and stand a chance to win a myriad of awards.'
    }
]

class Newsflash extends Component {
    render() {
        const settings = {
            infinite: true,
            slidesToShow: 1,
            slidesToScroll: 1,
            arrows: false,
            dots: false,
            autoplay: true,
            autoplaySpeed: 0,
            speed: 10000,
            cssEase: 'linear',
            variableWidth: true,
            pauseOnHover: true
        }
        return (
            <div className="col-md-12">
                <div className="ms-panel">
                    <div className="ms-panel-body ms-news-flash-container">
                        <div className="ms-news-update">
                            <span>News Update</span>
                        </div>
                        <Slider id="news-flash" {...settings}>
                            {news.map((item, i) => (
                                <li key={i}>
                                    <p>{item.title}</p>
                                </li>
                            ))}
                        </Slider>
                    </div>
                </div>
            </div>
        );
    }
}

export default Newsflash;
