import React, { Component } from 'react';
import { Doughnut } from 'react-chartjs-2';
import {Services} from "../../../Services";


// active-orders
function activeorders() {
    return {
        labels: ["Ehereum", "Bitcoin", "Dash", "Litecoin", "Peercoin"],
        datasets: [
            {
                label: "Population (millions)",
                borderColor: 'transparent',
                backgroundColor: ["#357ffa", "#f0ad4e", "#d9534f", "#445cc8", "#5cb85c"],
                data: [478, 267, 734, 784, 433]
            }
        ]
    }
}
// Options
const options = {
    cutoutPercentage: 70,
    animation: {
        animateScale: true
    },
    title: {
        display: false,
        text: 'Predicted world population (millions) in 2050'
    },
    legend: {
        position: 'left',
        display: false,
    },
}


class Activeorders extends Component {
  constructor(props, context) {
    super(props, context)
    this.state = {
      data: activeorders(),
      open: true,
      orderSummary: [],
      pie: {
        labels: [],
        datasets: [
          {
            label: "Invoice Summary",
            borderColor: 'transparent',
            backgroundColor: [],
            data: []
          }
        ]
      }
    };
    this.services = new Services(this);
  };

  componentDidMount() {
    this.getActiveOrders()
  }


  getActiveOrders = () => {
    let res = [
      {
        backgroundColor: "transparent",
        theme: "bg-success",
        themColor: "#094408",
        value: 749,
        name: "OVERDUE"
      }
    ]
    let labels = [];
    let backgroundColor = [];
    let data = [];

    res.forEach(function (item, index) {
      labels.push(item.name);
      backgroundColor.push("transparent");
      data.push(item.value);
      data.push(item.theme);
      console.log("Pie")
    })
    let pie = {
      labels: labels,
      datasets: [
        {
          label: "Invoice Summary",
          borderColor: 'transparent',
          backgroundColor: backgroundColor,
          data: data
        }
      ]
    }
    this.setState({orderSummary: res, pie:pie})
    // this.services.getData("orders-graph").then(res => {
    //   this.setState({orders: res.data});
    //   this.services.onCreateSuccess(res.data);
    // }).catch(err => {
    //   console.warn(err)
    // })
  }

  render() {
    const { orderSummary, pie } = this.state;
    console.log(pie)
    return (
      <div className="col-xl-5 col-md-12">
        <div className="ms-panel ms-panel-fh">
          <div className="ms-panel-header">
            <h6>Active Orders</h6>
            <p>Real tracking of Orders</p>
          </div>
          <div className="ms-panel-body">
            <div className="row">
              <div className="col-xl-4 col-md-4">
                <div className="ms-graph-labels column-direction">
                  {orderSummary.map(ord=>{
                    return (<div className="ms-chart-no-label" key={ord.theme}>
                      <span className={ord.theme}/>
                      <p>{ord.value} {ord.name}</p>
                    </div>)
                  })}
                </div>
              </div>
              <div className="col-xl-8 col-md-8">
                <Doughnut data={pie} options={options}/>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }
}

export default Activeorders;
