import React, { Component } from 'react';
import { Link } from 'react-router-dom';
import { Dropdown, NavLink } from 'react-bootstrap';
import { Line as LineChart } from 'react-chartjs-2';
 
// crypto-rating-graph

// Options
const options = {
    animation: false,
    scaleOverride: true,
    scaleSteps: 10,
    scaleStepWidth: 10,
    scaleStartValue: 0,
    elements: {
        line: {
            tension: 0
        }
    },
    legend: {
        display: false,
        position: "top"
    },
    scales: {
        yAxes: [{
            ticks: {
                beginAtZero: true,
                padding: 20,
                fontColor: "#A8A9AD"
            },
        }],
        xAxes: [{
            ticks: {
                padding: 20,
                beginAtZero: true,
                fontColor: "#A8A9AD"
            }
        }]
    }
}

class Bitcoingraph extends Component {
    constructor(props, context) {
        super(props, context)
        this.state = {
            data: {
              labels: props.labels,
              datasets: [{
                label: "Price",
                borderColor: '#357ffa',
                pointBorderWidth: 9,
                pointRadius: 9,
                pointBorderColor: 'transparent',
                pointHoverRadius: 8,
                pointHoverBorderWidth: 3,
                pointHoverBackgroundColor: 'white',
                pointHoverBorderColor: '#357ffa',
                pointBackgroundColor: 'transparent',
                fill: true,
                backgroundColor: "rgba(53,127,250,0.4)",
                borderWidth: 2,
                data: props.data
              }]
            },
            open: true,
        }
    };
    
    render() {
        return (
            <div className="col-xl-7 col-md-12">
                <div className="ms-panel ms-panel-fh ms-crypto-rating">
                    <div className="ms-panel-header header-mini">
                        <div className="d-flex justify-content-between">
                            <div className="ms-header-text">
                                <h6>Recent Deliveries Graph</h6>
                                <p>A graph of the recent deliveries in thousands of litres</p>
                            </div>
                        </div>
                    </div>
                    <div className="ms-panel-body">
                        <LineChart data={this.state.data} options={options} />
                    </div>
                </div>
            </div>
        );
    }
}

export default Bitcoingraph;
